// ── 标准输出写入失败 ─────────────────────────────────────────────────────────

#[cfg(unix)]
mod output_failures {
    use super::*;
    use std::fs::OpenOptions;
    use std::os::unix::io::{FromRawFd, RawFd};
    use std::process::Stdio;

    unsafe extern "C" {
        fn pipe(pipefd: *mut RawFd) -> std::os::raw::c_int;
    }

    /// 构造一个读端已经关闭的管道写端：子进程一写标准输出就收到 EPIPE，
    /// 模拟“结果交给管道而接收方已提前关闭”。
    fn closed_pipe_stdout() -> Stdio {
        let mut fds: [RawFd; 2] = [-1, -1];
        assert_eq!(unsafe { pipe(fds.as_mut_ptr()) }, 0);
        // 读端立即关闭（File 析构关闭该 fd）。
        drop(unsafe { std::fs::File::from_raw_fd(fds[0]) });
        Stdio::from(unsafe { std::fs::File::from_raw_fd(fds[1]) })
    }

    /// 以读不开写方式打开一个普通文件得到的 fd：对它写入会被内核拒绝，
    /// 模拟“标准输出被重定向到拒绝写入的位置”。
    fn read_only_stdout(path: &Path) -> Stdio {
        let file = OpenOptions::new()
            .read(true)
            .write(false)
            .open(path)
            .expect("open read-only fd");
        Stdio::from(file)
    }

    fn run_with_stdout(stdout: Stdio, args: &[&OsStr]) -> Output {
        inkseal()
            .args(args)
            .stdout(stdout)
            .output()
            .expect("failed to run inkseal")
    }

    /// 输出失败的完整约定：退出码 1、标准输出为空、标准错误只有一条
    /// inkseal: 的写入失败提示（保留系统原因），没有任何崩溃信息。
    fn assert_output_failure(output: &Output) -> String {
        assert_eq!(output.status.code(), Some(1), "exit code: {output:?}");
        assert!(
            output.stdout.is_empty(),
            "captured stdout must be empty: {:?}",
            String::from_utf8_lossy(&output.stdout)
        );
        let stderr = String::from_utf8(output.stderr.clone()).expect("stderr must be UTF-8");
        assert!(
            stderr.starts_with("inkseal: unable to write to standard output"),
            "must report an output failure, not another error: {stderr:?}"
        );
        assert!(
            stderr.ends_with('\n') && !stderr[..stderr.len() - 1].contains('\n'),
            "hint must be a single line: {stderr:?}"
        );
        // 系统给出的具体原因必须保留，且不能是 Rust 崩溃信息。
        assert!(!stderr.contains("panicked"), "must not crash: {stderr:?}");
        stderr
    }

    #[test]
    fn version_write_failure_exits_1_without_panic() {
        let output = run_with_stdout(closed_pipe_stdout(), &[OsStr::new("--version")]);

        let stderr = assert_output_failure(&output);
        assert!(stderr.to_lowercase().contains("pipe"), "keep OS reason: {stderr:?}");
    }

    #[test]
    fn digest_computed_but_not_delivered_is_still_a_failure() {
        let dir = TestDir::new("digest-dead-pipe");
        let path = dir.write_file(OsStr::new("hello.txt"), b"abc");

        let output = run_with_stdout(
            closed_pipe_stdout(),
            &[OsStr::new("digest"), path.as_os_str()],
        );

        let stderr = assert_output_failure(&output);
        // 不能把输出问题误报成读文件问题，也不能把摘要写到标准错误。
        assert!(!stderr.contains("cannot read"), "{stderr:?}");
        assert!(!stderr.contains(ABC_HEX), "digest must not move to stderr: {stderr:?}");
    }

    #[test]
    fn check_digest_match_but_not_delivered_is_still_a_failure() {
        let dir = TestDir::new("check-dead-pipe");
        let path = dir.write_file(OsStr::new("hello.txt"), b"abc");

        let output = run_with_stdout(
            closed_pipe_stdout(),
            &[
                OsStr::new("check-digest"),
                path.as_os_str(),
                OsStr::new(ABC_HEX),
            ],
        );

        let stderr = assert_output_failure(&output);
        // 不能补写成功标记，也不能误报为不匹配。
        assert!(!stderr.to_lowercase().contains("mismatch"), "{stderr:?}");
        assert!(!stderr.contains("OK"), "must not echo success marker to stderr: {stderr:?}");
    }

    #[test]
    fn check_digest_file_match_but_not_delivered_is_still_a_failure() {
        let dir = TestDir::new("check-file-dead-pipe");
        let path = dir.write_file(OsStr::new("hello.txt"), b"abc");
        // 摘要文件正是 digest 的输出形态（64 个小写十六进制字符加 LF）。
        let digest_path = dir.write_file(OsStr::new("hello.sha256"), format!("{ABC_HEX}\n").as_bytes());

        let output = run_with_stdout(
            closed_pipe_stdout(),
            &[
                OsStr::new("check-digest-file"),
                path.as_os_str(),
                digest_path.as_os_str(),
            ],
        );

        // 与 check-digest 完全相同的输出失败规则。
        let stderr = assert_output_failure(&output);
        assert!(!stderr.to_lowercase().contains("mismatch"), "{stderr:?}");
        assert!(!stderr.contains("OK"), "must not echo success marker to stderr: {stderr:?}");
    }

    #[test]
    fn redirect_to_unwritable_destination_is_output_failure() {
        let dir = TestDir::new("stdout-readonly");
        let target = dir.write_file(OsStr::new("sink"), b"");

        let output = run_with_stdout(
            read_only_stdout(&target),
            &[OsStr::new("--version")],
        );

        // 只读 fd 上的写入同样是输出失败，而非崩溃或成功。
        assert_output_failure(&output);
    }

    #[test]
    fn failure_branches_are_not_reported_as_output_errors_when_stdout_dead() {
        let dir = TestDir::new("dead-stdout-failures");
        let file = dir.write_file(OsStr::new("hello.txt"), b"abc");
        let missing = dir.path().join("nope.txt");
        let empty_hex = "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855";

        // 参数错误仍是退出码 2 与用法提示。
        let usage = run_with_stdout(closed_pipe_stdout(), &[OsStr::new("digest")]);
        assert_eq!(usage.status.code(), Some(2), "{usage:?}");
        let stderr = String::from_utf8_lossy(&usage.stderr);
        assert!(stderr.contains("Usage:"), "{stderr:?}");
        assert!(!stderr.contains("unable to write to standard output"), "{stderr:?}");

        // 摘要格式错误仍是退出码 2，且不访问文件。
        let bad_digest = run_with_stdout(
            closed_pipe_stdout(),
            &[
                OsStr::new("check-digest"),
                missing.as_os_str(),
                OsStr::new("abc"),
            ],
        );
        assert_eq!(bad_digest.status.code(), Some(2), "{bad_digest:?}");
        let stderr = String::from_utf8_lossy(&bad_digest.stderr);
        assert!(stderr.contains("Usage:"), "{stderr:?}");
        assert!(!stderr.contains("unable to write to standard output"), "{stderr:?}");

        // 文件打不开仍是退出码 1 与 cannot open，不是输出错误。
        let open_fail = run_with_stdout(
            closed_pipe_stdout(),
            &[OsStr::new("digest"), missing.as_os_str()],
        );
        assert_eq!(open_fail.status.code(), Some(1), "{open_fail:?}");
        let stderr = assert_failure(&open_fail);
        assert!(stderr.contains("cannot open"), "{stderr:?}");
        assert!(!stderr.contains("unable to write to standard output"), "{stderr:?}");

        // 内容不匹配仍按不匹配报告：没有成功结果需要写出，
        // 不应仅因标准输出不可用而变成输出错误。
        let mismatch = run_with_stdout(
            closed_pipe_stdout(),
            &[
                OsStr::new("check-digest"),
                file.as_os_str(),
                OsStr::new(empty_hex),
            ],
        );
        assert_mismatch(&mismatch, empty_hex, ABC_HEX);
        let stderr = String::from_utf8_lossy(&mismatch.stderr);
        assert!(!stderr.contains("unable to write to standard output"), "{stderr:?}");
    }
}

// ── 标准错误写入失败 ─────────────────────────────────────────────────────────
//
// 用户把标准错误接到另一个程序，而接收方提前关闭管道时，失败提示本身可能
// 写不出去。提示说明的是已经发生的失败：无论标准错误是否还可读，命令对
// 本次操作的判断（退出码 1 或 2）都不能改变，更不能因 eprintln! 在
// EPIPE/EBADF 上 panic 而以 101 崩溃。
#[cfg(unix)]
mod stderr_failures {
    use super::*;
    use std::fs::OpenOptions;
    use std::io;
    use std::os::raw::{c_int, c_void};
    use std::os::unix::io::{FromRawFd, RawFd};
    use std::process::Stdio;

    unsafe extern "C" {
        fn pipe(pipefd: *mut RawFd) -> c_int;
        fn pipe2(pipefd: *mut RawFd, flags: c_int) -> c_int;
        fn read(fd: RawFd, buf: *mut c_void, count: usize) -> isize;
        fn close(fd: RawFd) -> c_int;
        fn fcntl(fd: RawFd, cmd: c_int, arg: c_int) -> c_int;
    }

    /// 构造一个读端已经关闭的管道写端：子进程一写标准错误就收到 EPIPE，
    /// 模拟“错误提示交给管道而接收方已提前关闭”，且一个字节都送不出去。
    fn closed_pipe_stderr() -> Stdio {
        let mut fds: [RawFd; 2] = [-1, -1];
        assert_eq!(unsafe { pipe(fds.as_mut_ptr()) }, 0);
        // 读端立即关闭（File 析构关闭该 fd）。
        drop(unsafe { std::fs::File::from_raw_fd(fds[0]) });
        Stdio::from(unsafe { std::fs::File::from_raw_fd(fds[1]) })
    }

    /// 以只读方式打开一个普通文件得到的 fd：对它写入会被内核拒绝，
    /// 模拟“标准错误从一开始就被定向到拒绝写入的位置”。
    fn read_only_stderr(path: &Path) -> Stdio {
        let file = OpenOptions::new()
            .read(true)
            .write(false)
            .open(path)
            .expect("open read-only fd");
        Stdio::from(file)
    }

    fn run_with_stderr(stderr: Stdio, args: &[&OsStr]) -> Output {
        inkseal()
            .args(args)
            .stdout(Stdio::piped())
            .stderr(stderr)
            .output()
            .expect("failed to run inkseal")
    }

    /// 标准错误从第一个字节起就不可写时，所有用法错误仍以退出码 2
    /// 正常结束：不崩溃、不改报成功、不把用法说明挪到标准输出。
    #[test]
    fn usage_errors_with_dead_stderr_keep_exit_code_2() {
        let dir = TestDir::new("stderr-usage");
        let file = dir.write_file(OsStr::new("real.txt"), b"abc");
        let missing = dir.path().join("does-not-exist");
        // 内容非法的摘要文件：即便待核对文件不存在，也必须在访问它之前
        // 判定为用法错误（退出码 2）。
        let bad_digest_file = dir.write_file(OsStr::new("bad.sha256"), b"not-a-digest");

        let cases: Vec<Vec<&OsStr>> = vec![
            vec![],                                              // 无参数
            vec![OsStr::new("frobnicate")],                     // 未知子命令
            vec![OsStr::new("digest")],                         // 缺少文件参数
            vec![
                OsStr::new("digest"),
                file.as_os_str(),
                OsStr::new("extra"),
            ],                                                   // 多给参数
            vec![OsStr::new("check-digest")],                   // 缺少两个参数
            vec![OsStr::new("check-digest"), file.as_os_str()], // 缺少摘要参数
            vec![
                // 非法摘要 + 不存在的文件：格式校验先于文件访问，
                // 即使格式提示无法写出，也必须是 2，且不去打开文件。
                OsStr::new("check-digest"),
                missing.as_os_str(),
                OsStr::new("abc"),
            ],
            vec![OsStr::new("check-digest-file")],              // 缺少两个参数
            vec![OsStr::new("check-digest-file"), file.as_os_str()], // 缺少摘要文件参数
            vec![
                // 新命令同样先处理摘要文件：内容非法时即使待核对文件不存在，
                // 也是退出码 2，且不访问待核对文件。
                OsStr::new("check-digest-file"),
                missing.as_os_str(),
                bad_digest_file.as_os_str(),
            ],
        ];

        for args in cases {
            let output = run_with_stderr(closed_pipe_stderr(), &args);
            assert_eq!(
                output.status.code(),
                Some(2),
                "usage error must exit 2 even with dead stderr, args={args:?}: {output:?}"
            );
            // 必须是正常退出而非被信号终止（panic 会以 101 或 SIGABRT 结束）。
            assert!(output.status.code().is_some(), "must not be killed: {output:?}");
            assert!(
                output.stdout.is_empty(),
                "usage text must never move to stdout: {output:?}"
            );
            assert!(
                output.stderr.is_empty(),
                "dead pipe cannot carry any bytes: {output:?}"
            );
        }
    }

    /// 文件无法打开、路径为目录和摘要不匹配在标准错误完全不可写时，
    /// 仍以退出码 1 正常结束；读取失败同理（见下方只读 fd 之外的情形）。
    #[test]
    fn io_and_mismatch_failures_with_dead_stderr_keep_exit_code_1() {
        let dir = TestDir::new("stderr-failure");
        let file = dir.write_file(OsStr::new("hello.txt"), b"abc");
        let missing = dir.path().join("nope.txt");
        let subdir = dir.path().join("a-directory");
        fs::create_dir_all(&subdir).unwrap();
        let empty_hex =
            "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855";
        // 摘要文件：一份合法（digest 输出形态），一份不存在，一份是目录。
        let valid_digest_file =
            dir.write_file(OsStr::new("valid.sha256"), format!("{ABC_HEX}\n").as_bytes());
        let empty_digest_file =
            dir.write_file(OsStr::new("empty.sha256"), format!("{empty_hex}\n").as_bytes());
        let missing_digest = dir.path().join("missing.sha256");
        let digest_subdir = dir.path().join("digest-dir");
        fs::create_dir_all(&digest_subdir).unwrap();

        let cases: Vec<Vec<&OsStr>> = vec![
            vec![OsStr::new("digest"), missing.as_os_str()],
            vec![OsStr::new("digest"), subdir.as_os_str()],
            vec![
                OsStr::new("check-digest"),
                missing.as_os_str(),
                OsStr::new(ABC_HEX),
            ],
            vec![
                OsStr::new("check-digest"),
                subdir.as_os_str(),
                OsStr::new(ABC_HEX),
            ],
            vec![
                OsStr::new("check-digest"),
                file.as_os_str(),
                OsStr::new(empty_hex),
            ],
            // 摘要文件本身无法打开：退出码 1，与待核对文件无关。
            vec![
                OsStr::new("check-digest-file"),
                file.as_os_str(),
                missing_digest.as_os_str(),
            ],
            // 摘要文件指向目录（读取失败）：退出码 1。
            vec![
                OsStr::new("check-digest-file"),
                file.as_os_str(),
                digest_subdir.as_os_str(),
            ],
            // 摘要文件合法但待核对文件无法打开。
            vec![
                OsStr::new("check-digest-file"),
                missing.as_os_str(),
                valid_digest_file.as_os_str(),
            ],
            // 摘要文件合法但待核对文件是目录。
            vec![
                OsStr::new("check-digest-file"),
                subdir.as_os_str(),
                valid_digest_file.as_os_str(),
            ],
            // 摘要文件合法、待核对文件可读但内容不匹配。
            vec![
                OsStr::new("check-digest-file"),
                file.as_os_str(),
                empty_digest_file.as_os_str(),
            ],
        ];

        for args in cases {
            let output = run_with_stderr(closed_pipe_stderr(), &args);
            assert_eq!(
                output.status.code(),
                Some(1),
                "failure must keep exit 1 with dead stderr, args={args:?}: {output:?}"
            );
            assert!(
                output.stdout.is_empty(),
                "no success output may appear, args={args:?}: {output:?}"
            );
            assert!(output.stderr.is_empty(), "dead pipe carries no bytes: {output:?}");
        }
    }

    /// 标准错误从一开始就拒绝写入（fd 以只读方式打开，内核直接拒绝）时，
    /// 同样保留退出码且静默结束。
    #[test]
    fn read_only_stderr_keeps_exit_codes_without_panic() {
        let dir = TestDir::new("stderr-readonly");
        let sink = dir.write_file(OsStr::new("sink"), b"");
        let missing = dir.path().join("nope.txt");

        // 每次运行都需要一个新的只读 fd（Stdio 会消耗它）。
        let usage = run_with_stderr(
            read_only_stderr(&sink),
            &[OsStr::new("digest")],
        );
        assert_eq!(usage.status.code(), Some(2), "{usage:?}");
        assert!(usage.stdout.is_empty(), "{usage:?}");

        let open_fail = run_with_stderr(
            read_only_stderr(&sink),
            &[OsStr::new("digest"), missing.as_os_str()],
        );
        assert_eq!(open_fail.status.code(), Some(1), "{open_fail:?}");
        assert!(open_fail.stdout.is_empty(), "{open_fail:?}");
        assert!(
            !String::from_utf8_lossy(&open_fail.stderr).contains("panicked"),
            "must not crash: {open_fail:?}"
        );
    }

    /// 标准错误不可用本身不能使成功操作失败：版本查询、摘要计算、
    /// 核对通过仍照常把结果写到标准输出并以 0 退出。
    #[test]
    fn success_is_unaffected_when_stderr_is_dead() {
        let dir = TestDir::new("stderr-dead-success");
        let path = dir.write_file(OsStr::new("hello.txt"), b"abc");
        // digest 输出形态的摘要文件：64 个小写十六进制字符加 LF。
        let digest_path =
            dir.write_file(OsStr::new("hello.sha256"), format!("{ABC_HEX}\n").as_bytes());

        let version = run_with_stderr(closed_pipe_stderr(), &[OsStr::new("--version")]);
        assert_eq!(version.status.code(), Some(0), "{version:?}");
        assert_eq!(version.stdout, b"inkseal 0.1.0\n", "{version:?}");
        assert!(version.stderr.is_empty());

        let digest = run_with_stderr(
            closed_pipe_stderr(),
            &[OsStr::new("digest"), path.as_os_str()],
        );
        assert_eq!(digest.status.code(), Some(0), "{digest:?}");
        assert_eq!(digest.stdout, format!("{ABC_HEX}\n").as_bytes(), "{digest:?}");

        let check = run_with_stderr(
            closed_pipe_stderr(),
            &[
                OsStr::new("check-digest"),
                path.as_os_str(),
                OsStr::new(ABC_HEX),
            ],
        );
        assert_eq!(check.status.code(), Some(0), "{check:?}");
        assert_eq!(check.stdout, b"OK\n", "{check:?}");

        // check-digest-file 核对通过同样只取决于标准输出。
        let check_file = run_with_stderr(
            closed_pipe_stderr(),
            &[
                OsStr::new("check-digest-file"),
                path.as_os_str(),
                digest_path.as_os_str(),
            ],
        );
        assert_eq!(check_file.status.code(), Some(0), "{check_file:?}");
        assert_eq!(check_file.stdout, b"OK\n", "{check_file:?}");
    }

    /// 成功结果无法写到标准输出、且连输出失败提示也无法写到标准错误时，
    /// 按既有规则以 1 静默结束：两个流都为空，也没有崩溃信息。
    #[test]
    fn undeliverable_success_with_both_streams_dead_is_silent_exit_1() {
        let dir = TestDir::new("both-dead");
        let path = dir.write_file(OsStr::new("hello.txt"), b"abc");
        let digest_path =
            dir.write_file(OsStr::new("hello.sha256"), format!("{ABC_HEX}\n").as_bytes());

        let cases: Vec<Vec<&OsStr>> = vec![
            vec![OsStr::new("--version")],
            vec![OsStr::new("digest"), path.as_os_str()],
            vec![
                OsStr::new("check-digest"),
                path.as_os_str(),
                OsStr::new(ABC_HEX),
            ],
            vec![
                OsStr::new("check-digest-file"),
                path.as_os_str(),
                digest_path.as_os_str(),
            ],
        ];
        for args in cases {
            let output = inkseal()
                .args(&args)
                .stdout(closed_pipe_stderr())
                .stderr(closed_pipe_stderr())
                .output()
                .expect("failed to run inkseal");
            assert_eq!(output.status.code(), Some(1), "args={args:?}: {output:?}");
            assert!(output.stdout.is_empty(), "args={args:?}: {output:?}");
            assert!(output.stderr.is_empty(), "args={args:?}: {output:?}");
        }
    }

    /// 管道只接收了提示的前几个字节、接收方便提前关闭时，子进程在后续
    /// 写入上收到 EPIPE：已发出的字节保留，退出码仍为 1，进程正常结束。
    ///
    /// 确定性地制造“部分送达后失败”：把管道容量缩到一个页面（4096），
    /// 再让提示本身远大于该容量（超长路径触发的文件错误）。内核对
    /// 大于 PIPE_BUF 的阻塞写是非原子的——写满容量后子进程阻塞等待，
    /// 此时关闭读端，剩余写入必然以 EPIPE 失败，而提示开头的字节已经
    /// 送达。若提示仍经由 eprintln! 写出，子进程会 panic（101/信号）。
    #[cfg(target_os = "linux")]
    #[test]
    fn partial_stderr_write_failure_keeps_exit_code_without_panic() {
        const F_SETPIPE_SZ: c_int = 1024 + 7;
        // arm64/x86-64 Linux 上 O_CLOEXEC 均为 02000000（八进制）。
        const O_CLOEXEC: c_int = 0o2000000;

        let dir = TestDir::new("stderr-partial");
        // 单条错误提示远超 PIPE_BUF（4096）：含约 10000 字节的路径名。
        // 该路径无法打开（ENAMETOOLONG），属于退出码 1 的文件访问失败。
        let path = dir.path().join("A".repeat(10_000));

        // pipe2(…, O_CLOEXEC) 至关重要：读端不能被子进程继承，否则测试
        // 关闭自己的读端副本后子进程仍持有读端，会无限阻塞地写给自己。
        let mut fds: [RawFd; 2] = [-1, -1];
        assert_eq!(
            unsafe { pipe2(fds.as_mut_ptr(), O_CLOEXEC) },
            0,
            "{}",
            io::Error::last_os_error()
        );
        let set = unsafe { fcntl(fds[1], F_SETPIPE_SZ, 4096) };
        assert!(set >= 0, "shrink pipe: {}", io::Error::last_os_error());

        let write_end = unsafe { std::fs::File::from_raw_fd(fds[1]) };
        let child = inkseal()
            .args(["digest"])
            .arg(path.as_os_str())
            .stdout(Stdio::piped())
            .stderr(Stdio::from(write_end))
            .spawn()
            .expect("failed to run inkseal");

        // 子进程的首次写入已填满 4096 字节容量后阻塞；一次性取出这段
        // 连续的提示前缀（在子进程补入更多字节之前读完）。
        let mut prefix = vec![0u8; 4096];
        read_full(fds[0], &mut prefix);
        assert!(
            prefix.starts_with(b"inkseal: cannot open '"),
            "delivered prefix must be the real hint: {:?}",
            String::from_utf8_lossy(&prefix[..40.min(prefix.len())])
        );

        // 接收方提前关闭：管道中已送达的提示前缀无需也无法补齐，
        // 子进程剩余写入立即失败，但必须仍以退出码 1 正常结束。
        assert_eq!(unsafe { close(fds[0]) }, 0);

        let output = child.wait_with_output().expect("failed to wait");
        assert_eq!(output.status.code(), Some(1), "{output:?}");
        assert!(output.stdout.is_empty(), "{output:?}");
        assert!(
            !String::from_utf8_lossy(&output.stderr).contains("panicked"),
            "must not crash: {output:?}"
        );
    }

    /// 阻塞地从 fd 读满 `buf`，EINTR 立即重试。
    #[cfg(target_os = "linux")]
    fn read_full(fd: RawFd, mut buf: &mut [u8]) {
        while !buf.is_empty() {
            let n = unsafe { read(fd, buf.as_mut_ptr().cast::<c_void>(), buf.len()) };
            assert!(n > 0, "read pipe: {}", io::Error::last_os_error());
            let len = n as usize;
            buf = &mut buf[len..];
        }
    }
}

// ── 读取临时受阻后继续（EINTR 与短读）与部分读取后失败 ─────────────────────────
//
// check-digest 打开文件后，读取循环必须持续到明确读到文件结束：一次 read
// 只返回少量字节（短读）不是结束，可恢复的临时中断（EINTR，一个字节都没
// 读到）也不是结束，二者都必须在原位置继续；只有 read 明确返回 0 才是
// 结束。若已读入部分内容后出现真正的读取错误，这是读取失败：退出码 1、
// 标准输出为空、沿用 `cannot read` 提示并给出路径与具体原因，绝不能因为
// “已经读到的前缀摘要恰好等于预期摘要”而报 OK，也不能退化为不匹配。
//
// 与输出侧重试相同，这类读取序列无法从父进程一侧确定性地制造，因此用
// LD_PRELOAD 垫片拦截子进程的 read，按 INKSEAL_READ_SHIM 给出的逗号分隔
// 脚本逐步注入临时中断、短读与不可恢复错误，脚本耗尽后透传真实读取。
#[cfg(target_os = "linux")]
mod read_retry {
    use super::*;
    use std::sync::OnceLock;

    /// LD_PRELOAD 垫片源码：拦截子进程对已打开输入文件（fd 3 及以上）的
    /// read 调用，按 INKSEAL_READ_SHIM 的逗号分隔脚本逐步执行，脚本耗尽
    /// 后透传真实读取。步骤：`i` = 返回 EINTR（不读到任何字节）；
    /// `sN` = 最多读取 N 字节的短读；`eN` = 返回 errno 为 N 的真实错误。
    ///
    /// 垫片自身读取时直接走 read 系统调用，绕开对 read 符号的拦截，否则
    /// 透传分支会递归进入自己。垫片不引入任何 crate 依赖，测试运行时用
    /// rustc 编译为 cdylib。
    const SHIM_SOURCE: &str = r#"
use std::os::raw::{c_int, c_void};
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::OnceLock;

#[derive(Clone, Copy)]
enum Step {
    Intr,
    Short(usize),
    Errno(c_int),
}

fn steps() -> &'static [Step] {
    static STEPS: OnceLock<Vec<Step>> = OnceLock::new();
    STEPS
        .get_or_init(|| {
            std::env::var("INKSEAL_READ_SHIM")
                .unwrap_or_default()
                .split(',')
                .filter(|token| !token.is_empty())
                .map(|token| {
                    if token == "i" {
                        Step::Intr
                    } else if let Some(n) = token.strip_prefix('s') {
                        Step::Short(n.parse().expect("short-read length"))
                    } else if let Some(e) = token.strip_prefix('e') {
                        Step::Errno(e.parse().expect("errno"))
                    } else {
                        panic!("unknown shim step: {token}");
                    }
                })
                .collect()
        })
        .as_slice()
}

static STEP_INDEX: AtomicUsize = AtomicUsize::new(0);

unsafe extern "C" {
    fn syscall(number: isize, ...) -> isize;
    fn __errno_location() -> *mut c_int;
}

#[cfg(target_arch = "x86_64")]
const SYS_READ: isize = 0;
#[cfg(target_arch = "aarch64")]
const SYS_READ: isize = 63;

const EINTR: c_int = 4;

fn fail(errno: c_int) -> isize {
    unsafe { *__errno_location() = errno };
    -1
}

fn real_read(fd: c_int, buf: *mut c_void, count: usize) -> isize {
    // 直接发起 read 系统调用：不能调用 libc 的 read，否则会被本垫片
    // 再次拦截而无限递归。
    unsafe { syscall(SYS_READ, fd, buf, count) }
}

#[no_mangle]
pub unsafe extern "C" fn read(fd: c_int, buf: *mut c_void, count: usize) -> isize {
    // 只驱动被核对的输入文件：子进程的标准描述符固定为 0–2，命令打开
    // 文件后得到 fd 3。脚本耗尽后一律透传，启动阶段即便存在其他读取
    // （已确认本进程没有）也不会受到影响。
    if fd >= 3 {
        let index = STEP_INDEX.fetch_add(1, Ordering::SeqCst);
        match steps().get(index) {
            Some(Step::Intr) => return fail(EINTR),
            Some(Step::Errno(errno)) => return fail(*errno),
            Some(Step::Short(limit)) => return real_read(fd, buf, count.min(*limit)),
            None => {}
        }
    }
    real_read(fd, buf, count)
}
"#;

    /// Linux 上各架构一致的 errno 值。
    const EIO: i32 = 5;
    const EACCES: i32 = 13;

    /// errno 5（EIO）经标准库显示的具体原因。
    const EIO_REASON: &str = "Input/output error (os error 5)";
    /// errno 13（EACCES）经标准库显示的具体原因。
    const EACCES_REASON: &str = "Permission denied (os error 13)";

    /// 每个测试进程只编译一次垫片，产物放在临时目录。
    fn read_shim() -> &'static Path {
        static SHIM: OnceLock<PathBuf> = OnceLock::new();
        SHIM.get_or_init(|| {
            let dir = std::env::temp_dir()
                .join(format!("inkseal-read-shim-{}", std::process::id()));
            fs::create_dir_all(&dir).expect("create shim dir");
            let source = dir.join("read_shim.rs");
            let library = dir.join("libinkseal_read_shim.so");
            fs::write(&source, SHIM_SOURCE).expect("write shim source");
            let rustc = std::env::var_os("RUSTC").unwrap_or_else(|| "rustc".into());
            let status = Command::new(rustc)
                .arg("--edition=2021")
                .arg("--crate-type=cdylib")
                .arg("-O")
                .arg("-o")
                .arg(&library)
                .arg(&source)

input.old_string:
    Ok(Sha256Digest(hasher.finalize().into()))
}

#[cfg(test)]

input.new_string:
    Ok(Sha256Digest(hasher.finalize().into()))
}

// ── Ed25519 公钥导入 ─────────────────────────────────────────────────────────
//
// 入口只接受一种形态：DER 编码的 SubjectPublicKeyInfo（RFC 5280），且算法
// 标识为 RFC 8410 规定的 Ed25519（OID 1.3.101.112）。公钥因此是与
// [`Sha256Digest`] 完全独立的类型——二者底层都只是 32 字节，但语义、解析
// 入口与文本表示都不可互换，公钥不会被当作摘要解析，摘要也不会被当作公钥。
//
// 解析器手写且零依赖：只实现 SPKI 所需的 DER 子集，并对长度编码与边界做
// 完整、规范（strict DER）校验。任何截断、声明长度与实际内容不符、非规范
// 长度编码、容器中的多余字段或对象之后的多余字节都属于编码损坏，绝不忽略
// 剩余内容或自动补齐。

/// 从 DER 编码的 SubjectPublicKeyInfo 导入的 Ed25519 公钥。
///
/// 该类型与 [`Sha256Digest`] 明确区分：它只由
/// [`import_ed25519_public_key`] 产生，不能从十六进制文本构造，也不会被
/// 当作摘要解析。它持有的是公钥本身的 32 个原始字节（RFC 8032 编码点），
/// **不是**公钥或任何内容的 SHA-256 摘要。
#[derive(Clone, Copy, PartialEq, Eq, Hash)]
pub struct Ed25519PublicKey([u8; 32]);

impl Ed25519PublicKey {
    /// 返回公钥原样的 32 字节（RFC 8032 的公钥编码点）。
    pub fn as_bytes(&self) -> &[u8; 32] {
        &self.0
    }

    /// 返回 64 个小写十六进制字符，表示公钥本身。
    ///
    /// 与 [`Sha256Digest::to_hex`] 形状相同（32 字节的十六进制展开），
    /// 但二者语义不同：这里是公钥字节的文本表示，前导零保留，不含标签、
    /// 空白或换行，也不是公钥的 SHA-256 摘要。
    pub fn to_hex(&self) -> String {
        bytes_to_lower_hex(&self.0)
    }
}

impl fmt::Display for Ed25519PublicKey {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.to_hex())
    }
}

impl fmt::Debug for Ed25519PublicKey {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "Ed25519PublicKey({self})")
    }
}

/// SubjectPublicKeyInfo 中出现的算法标识，按内容节点（OID）的原始 DER
/// 内容字节逐字节比较。
///
/// 目前唯一可比较的具名值是 Ed25519（`1.3.101.112`，RFC 8410）；
/// 其他标识以 [`Other`](Self::Other) 原样保留其 DER 内容字节，调用方可
/// 自行解码展示，库不会为不支持的算法猜测文本名称。
#[derive(Clone, Copy, PartialEq, Eq, Hash)]
pub enum PublicKeyAlgorithm {
    /// Ed25519：OID 1.3.101.112（RFC 8410）。
    Ed25519,
    /// 其他算法标识：携带 OID 的原始 DER 内容字节（弧段值的压缩编码，
    /// 不含 OBJECT IDENTIFIER 的标签与长度）。
    Other([u8; Self::OTHER_CAPACITY]),
}

impl PublicKeyAlgorithm {
    /// 未知 OID 最多保留的内容字节数。
    ///
    /// 合法的 OID 内容是一串 7 位基数字（base-128）弧段；前导
    /// `0x80`/`0xFF` 延续字节是非规范编码，属于整体编码损坏，不会走到
    /// 算法比较，因此这里只需容纳实际可能出现的合法 OID。任意实际算法
    /// OID 都远短于此上限；超出同样按编码损坏处理，而不是静默截断。
    pub const OTHER_CAPACITY: usize = 64;

    /// 按 OID 的内容字节判定：恰好是 Ed25519（1.3.101.112）的编码。
    fn from_oid_content(content: &[u8]) -> Result<PublicKeyAlgorithm, KeyImportError> {
        const ED25519_OID: &[u8] = &[0x2b, 0x65, 0x70]; // 1.3.101.112
        if content == ED25519_OID {
            Ok(PublicKeyAlgorithm::Ed25519)
        } else {
            if content.is_empty() || content.len() > Self::OTHER_CAPACITY {
                return Err(KeyImportError::Malformed);
            }
            // 合法 OID 内容由一串 base-128 弧段组成：除每段最后一个字节
            // 的高位为 0 外，其余延续字节高位为 1。任何前导 0x80（非规范
            // 延续）或末字节仍带高位（截断的弧段）都是损坏编码。
            let mut cont = false;
            for &b in content {
                if !cont && b == 0x80 {
                    return Err(KeyImportError::Malformed);
                }
                cont = b & 0x80 != 0;
            }
            if cont {
                return Err(KeyImportError::Malformed);
            }
            let mut buf = [0u8; Self::OTHER_CAPACITY];
            buf[..content.len()].copy_from_slice(content);
            Ok(PublicKeyAlgorithm::Other(buf))
        }
    }

    /// 是否为受支持的 Ed25519 算法标识。
    pub fn is_ed25519(&self) -> bool {
        matches!(self, PublicKeyAlgorithm::Ed25519)
    }

    /// 其他算法标识的原始 OID 内容字节；Ed25519 返回 `None`。
    ///
    /// 返回的是 OBJECT IDENTIFIER 内容节点的原始 DER 字节（不含标签与
    /// 长度），可供调用方按点分十进制自行解码展示；库不替调用方猜测其
    /// 文本名称。
    pub fn oid_bytes(&self) -> Option<&[u8]> {
        match self {
            PublicKeyAlgorithm::Ed25519 => None,
            PublicKeyAlgorithm::Other(bytes) => Some(bytes.as_slice()),
        }
    }
}

impl fmt::Debug for PublicKeyAlgorithm {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            PublicKeyAlgorithm::Ed25519 => f.write_str("Ed25519(1.3.101.112)"),
            PublicKeyAlgorithm::Other(bytes) => {
                write!(f, "Other({})", fmt_bytes_to_hex(bytes))
            }
        }
    }
}

/// 导入 Ed25519 公钥失败时返回的类型化错误。
///
/// 调用方无需解析提示字符串即可区分两类失败：
///
/// - [`Malformed`](Self::Malformed)：输入不是一份完整、规范的 DER
///   SubjectPublicKeyInfo，或其内部结构不符合 Ed25519 公钥的规定——截断、
///   长度不符、非规范长度编码、多余字段、尾随字节、参数写成 `NULL`、
///   位串有未使用位、公钥不是恰好 32 字节等都属于这一类。裸公钥、
///   十六进制文本与 PEM 文本同样不被这个入口接受。
/// - [`UnsupportedAlgorithm`](Self::UnsupportedAlgorithm)：整体 DER 结构
///   完整合法，但算法标识不是 Ed25519。实际标识随错误保留，可直接展示。
///
/// 只有“结构完整、DER 合法”时才可能出现算法不支持；编码已损坏时一律是
/// [`Malformed`](Self::Malformed)，不会因为损坏数据中局部出现某个其他
/// 算法的 OID 字节就改报算法不支持。任何失败都不会产生可继续使用的公钥。
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum KeyImportError {
    /// DER 编码或公钥结构不合法（含输入为空、被截断、非规范编码、多余
    /// 字段、尾随字节、参数非缺省、位串未使用位非零、公钥长度不符）。
    Malformed,
    /// SubjectPublicKeyInfo 结构合法，但算法标识不是 Ed25519；携带实际
    /// 算法标识。
    UnsupportedAlgorithm(PublicKeyAlgorithm),
}

impl KeyImportError {
    /// 是否为编码或公钥结构不合法（而非算法不支持）。
    pub fn is_malformed(&self) -> bool {
        matches!(self, KeyImportError::Malformed)
    }

    /// 结构合法但算法不被支持时，返回其中保留的实际算法标识；
    /// 编码损坏时返回 `None`。
    pub fn unsupported_algorithm(&self) -> Option<&PublicKeyAlgorithm> {
        match self {
            KeyImportError::Malformed => None,
            KeyImportError::UnsupportedAlgorithm(algo) => Some(algo),
        }
    }
}

impl fmt::Display for KeyImportError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            KeyImportError::Malformed => f.write_str(
                "malformed Ed25519 public key: expected one complete DER SubjectPublicKeyInfo \
                 (RFC 8410), but the encoding is invalid or truncated",
            ),
            KeyImportError::UnsupportedAlgorithm(PublicKeyAlgorithm::Ed25519) => {
                // 不会发生：Ed25519 是受支持算法，保留分支以保证匹配穷尽。
                f.write_str("unexpected Ed25519 algorithm identifier")
            }
            KeyImportError::UnsupportedAlgorithm(PublicKeyAlgorithm::Other(oid)) => write!(
                f,
                "unsupported public key algorithm with OID content {}; only Ed25519 \
                 (1.3.101.112, RFC 8410) is accepted",
                fmt_bytes_to_hex(oid)
            ),
        }
    }
}

impl Error for KeyImportError {}

/// DER 通用标签中本解析器用到的值。
const der_tag: u8 = {
    // 用常量而不是散落的魔法数字；SEQUENCE / BIT STRING / OID / NULL。
    0
};
const DER_TAG_BOOLEAN: u8 = 0x01;
const DER_TAG_INTEGER: u8 = 0x02;
const DER_TAG_BIT_STRING: u8 = 0x03;
const DER_TAG_NULL: u8 = 0x05;
const DER_TAG_OID: u8 = 0x06;
const DER_TAG_SEQUENCE: u8 = 0x30;
// 让上面的占位常量实际参与一次无副作用的引用检查是多余的：直接不保留它。
const _: u8 = der_tag;

/// 读取一个 DER TLV，返回 `(标签, 值字节, 标签后剩余的全部字节)`。
///
/// 严格校验：标识符必须是单字节通用标签（首字节 `0x1f` 的多字节标签
/// 形式直接拒绝）；长度必须是规范 DER——短形式或最短必要的长形式，
/// `0x81 0x00` 之类非最小编码与长形式前导零都拒绝；声明长度必须与实际
/// 内容相符，截断与对象后的多余字节由调用方按“剩余必须恰好用尽”处理。
fn der_read_tlv(data: &[u8]) -> Result<(u8, &[u8], &[u8]), KeyImportError> {
    let (&tag, rest) = data.split_first().ok_or(KeyImportError::Malformed)?;
    // 多字节标签号（tag number 0x1f..=0x3e 的低位全 1）不用于 SPKI 的
    // 任何规定节点，一律拒绝。
    if tag & 0x1f == 0x1f {
        return Err(KeyImportError::Malformed);
    }
    let (&first_len, mut rest) = rest.split_first().ok_or(KeyImportError::Malformed)?;

    let length = match first_len {
        // 短形式：0..=127。
        0..=0x7f => first_len as usize,
        // 长形式：低 7 位是后续长度字节数；0x80（不确定长度）不是 DER，
        0x80 => return Err(KeyImportError::Malformed),
        0x81.. => {
            let n = (first_len & 0x7f) as usize;
            // 长度字节数本身有界：超过指针宽度或剩余数据都属于损坏。
            if n == 0 || n > rest.len() || n > size_of::<usize>() {
                return Err(KeyImportError::Malformed);
            }
            let (len_bytes, after) = rest.split_at(n);
            // 首字节为零说明可用更短的长形式甚至短形式表示，非最小编码。
            if len_bytes[0] == 0 {
                return Err(KeyImportError::Malformed);
            }
            let mut length: usize = 0;
            for &b in len_bytes {
                length = (length << 8) | b as usize;
            }
            // 一个长度字节（n == 1）只能表示 >= 128；若值更小，短形式
            // 才是规范编码。
            if n == 1 && length < 0x80 {
                return Err(KeyImportError::Malformed);
            }
            // 多个长度字节时，首位为零已在上面拒绝，这里无需再判下界。
            rest = after;
            length
        }
    };

    let (value, remainder) = rest.split_at_checked(length).ok_or(KeyImportError::Malformed)?;
    Ok((tag, value, remainder))
}

/// 要求 `data` 是恰好一个带给定标签的 TLV，且其值之后没有任何剩余字节。
fn der_exact_one(tag: u8, data: &[u8]) -> Result<&[u8], KeyImportError> {
    let (found, value, rest) = der_read_tlv(data)?;
    if found != tag || !rest.is_empty() {
        return Err(KeyImportError::Malformed);
    }
    Ok(value)
}

/// 导入一份 DER 编码的 SubjectPublicKeyInfo 公钥，仅接受 RFC 8410 的
/// Ed25519 公钥。
///
/// 入参是二进制公钥容器的原始字节，不是十六进制文本、PEM 文本，也不是
/// 去掉容器后的裸 32 字节公钥；本入口不做任何格式猜测或文本转换。
///
/// 接受的结构（RFC 5280 SubjectPublicKeyInfo，RFC 8410 对 Ed25519 的
/// 规定）：
///
/// ```text
/// SubjectPublicKeyInfo ::= SEQUENCE {
///   algorithm        AlgorithmIdentifier,  -- 恰好 OID 1.3.101.112，参数缺省
///   subjectPublicKey BIT STRING            -- 未使用位为 0，内容恰好 32 字节
/// }
/// AlgorithmIdentifier ::= SEQUENCE {
///   algorithm  OBJECT IDENTIFIER,          -- 1.3.101.112
///   parameters ANY OPTIONAL ABSENT         -- Ed25519 必须缺省，写成 NULL 也拒绝
/// }
/// ```
///
/// 输入必须是一份完整、规范的 DER 对象：截断、声明长度与实际内容不符、
/// 非规范长度编码、容器中出现多余字段（AlgorithmIdentifier 的任何参数、
/// 外层 SEQUENCE 的第三个成员等）或对象之后还有字节都一律拒绝，剩余
/// 内容不会被忽略，缺失字段也不会自动补齐。
///
/// 成功只表示编码被接受：它不验证任何文件签名，也不确认公钥持有者的
/// 身份；调用方需要另行进行签名验证与带外的身份确认。
///
/// 失败时返回 [`KeyImportError`]：结构完整、DER 合法但算法标识不是
/// Ed25519 时为
/// [`UnsupportedAlgorithm`](KeyImportError::UnsupportedAlgorithm)，并保留
/// 实际标识供展示；整体编码损坏时为 [`Malformed`](KeyImportError::Malformed)。
pub fn import_ed25519_public_key(der: &[u8]) -> Result<Ed25519PublicKey, KeyImportError> {
    // 外层：恰好一个 SEQUENCE，之后不得有任何字节。
    let spki = der_exact_one(DER_TAG_SEQUENCE, der)?;

    // 第一个成员：AlgorithmIdentifier SEQUENCE。
    let (tag, alg_content, rest) = der_read_tlv(spki)?;
    if tag != DER_TAG_SEQUENCE {
        return Err(KeyImportError::Malformed);
    }

    // AlgorithmIdentifier 的第一个成员：OBJECT IDENTIFIER。
    let (tag, oid_content, after_oid) = der_read_tlv(alg_content)?;
    if tag != DER_TAG_OID {
        return Err(KeyImportError::Malformed);
    }
    // parameters 必须缺省：AlgorithmIdentifier 内 OID 之后不能再有任何
    // TLV——显式 NULL（05 00）或其他参数都属于结构不合法，绝不按缺省
    // 参数处理。
    if !after_oid.is_empty() {
        return Err(KeyImportError::Malformed);
    }

    // 先把算法标识解析出来。OID 本身编码不合法（空内容、非规范弧段等）
    // 属于整体编码损坏，而不是“其他算法”。
    let algorithm = PublicKeyAlgorithm::from_oid_content(oid_content)?;

    // 第二个成员：subjectPublicKey BIT STRING。
    let (tag, bit_string, after_bitstring) = der_read_tlv(rest)?;
    if tag != DER_TAG_BIT_STRING {
        return Err(KeyImportError::Malformed);
    }
    // 外层 SEQUENCE 中 BIT STRING 之后不得再有第三个成员或任何多余字节。
    if !after_bitstring.is_empty() {
        return Err(KeyImportError::Malformed);
    }

    // 只有结构完整、算法确认为 Ed25519 后才取出公钥字节。其他算法在
    // 此之前返回 UnsupportedAlgorithm：例如某算法的 BIT STRING 为空，
    // 那仍是“合法 SPKI + 不支持的算法”，而不是编码损坏。
    if algorithm != PublicKeyAlgorithm::Ed25519 {
        return Err(KeyImportError::UnsupportedAlgorithm(algorithm));
    }

    // BIT STRING 的第一个内容字节是“未使用位数”，Ed25519 公钥必须为零，
    // 其后恰好是 32 字节公钥。空位串（连未使用位数字节都没有）、非零
    // 未使用位、公钥长度不是 32 都拒绝。
    let (&unused_bits, key_bytes) =
        bit_string.split_first().ok_or(KeyImportError::Malformed)?;
    if unused_bits != 0 {
        return Err(KeyImportError::Malformed);
    }
    let key: [u8; 32] = key_bytes
        .try_into()
        .map_err(|_| KeyImportError::Malformed)?;

    Ok(Ed25519PublicKey(key))
}

/// 把固定长度字节展开为小写十六进制字符串（摘要与公钥共用同一规则）。
fn bytes_to_lower_hex(bytes: &[u8]) -> String {
    let mut hex = String::with_capacity(bytes.len() * 2);
    for byte in bytes {
        hex.push(char::from_digit((byte >> 4) as u32, 16).unwrap());
        hex.push(char::from_digit((byte & 0x0f) as u32, 16).unwrap());
    }
    hex
}

/// 与 [`bytes_to_lower_hex`] 相同的展开，但直接写到 [`fmt::Formatter`]，
/// 供 Debug 输出复用。
fn fmt_bytes_to_hex(bytes: &[u8]) -> String {
    bytes_to_lower_hex(bytes)
}

