        let mut body = valid[2..].to_vec();
        body.extend_from_slice(&[0x05, 0x00]);
        let with_third = der(0x30, &body);
        assert_eq!(
            import_ed25519_public_key(&with_third),
            Err(KeyImportError::Malformed)
