        assert_eq!(
            import_ed25519_public_key(&der(0x30, &body)),
            Err(KeyImportError::Malformed)
        );

        // algorithm 成员不是 OID（放一个 NULL）。
        let mut body = der(0x30, &[0x05, 0x00]);
        body.extend_from_slice(&der(0x03, &bs_content));
        assert_eq!(
            import_ed25519_public_key(&der(0x30, &body)),
            Err(KeyImportError::Malformed)
        );

