        let mut body = der(0x30, &oid);
        body.extend_from_slice(&der(0x04, &{
            let mut v = vec![0x00];
            v.extend_from_slice(&[1u8; 32]);
            v
        }));
        assert_eq!(
            import_ed25519_public_key(&der(0x30, &body)),
            Err(KeyImportError::Malformed)
        );

        // 内层 OID 声明长度与实际不符：algId SEQUENCE 中放 06 05 2b 65 70。
        let mut bad_oid_alg = vec![0x30, 0x06, 0x06, 0x05, 0x2b, 0x65, 0x70, 0x00];
        // 用完整重写更直观：SEQUENCE { SEQ{ 06 05 <3 bytes> } ... } 期望失败。
        let _ = bad_oid_alg.len();
        bad_oid_alg = der(
            0x30,
            &{
                let mut v = der(0x30, &[0x06, 0x05, 0x2b, 0x65, 0x70]);
                v.extend_from_slice(&der(0x03, &{
