use inkseal::{import_ed25519_public_key, KeyImportError};
use std::env;

fn main() {
    for path in env::args().skip(1) {
        let data = std::fs::read(&path).unwrap();
        match import_ed25519_public_key(&data) {
            Ok(key) => println!("{path}: OK {}", key.to_hex()),
            Err(KeyImportError::Malformed) => println!("{path}: Malformed"),
            Err(KeyImportError::UnsupportedAlgorithm(a)) => {
                println!("{path}: UnsupportedAlgorithm oid={:?} ed25519={}",
                         a.oid_bytes().map(hex::to_owned_from_slice), a.is_ed25519());
            }
        }
    }
}

mod hex {
    pub fn to_owned_from_slice(b: &[u8]) -> String {
        let mut s = String::new();
        for x in b { s.push_str(&format!("{x:02x}")); }
        s
    }
}
